from pathlib import Path
import base64, re

ROOT=Path('Detecteur360Quebec')
RES=ROOT/'app/src/main/res'
DRAWABLE=RES/'drawable'
DRAWABLE.mkdir(parents=True, exist_ok=True)

for old in [DRAWABLE/'detecteur_logo.jpg', DRAWABLE/'detecteur_logo.png', DRAWABLE/'detecteur_logo.webp']:
    if old.exists(): old.unlink()

logo=''''''
(DRAWABLE/'detecteur_logo.webp').write_bytes(base64.b64decode(logo))

key=''''''
(ROOT/'d360-release.jks').write_bytes(base64.b64decode(key))

manifest=ROOT/'app/src/main/AndroidManifest.xml'
m=manifest.read_text(encoding='utf-8')
if 'android:icon=' not in m:
    m=m.replace('<application\n','<application\n        android:icon="@drawable/detecteur_logo"\n        android:roundIcon="@drawable/detecteur_logo"\n',1)
else:
    m=re.sub(r'android:icon="[^"]+"','android:icon="@drawable/detecteur_logo"',m)
    if 'android:roundIcon=' in m:
        m=re.sub(r'android:roundIcon="[^"]+"','android:roundIcon="@drawable/detecteur_logo"',m)
    else:
        m=m.replace('android:icon="@drawable/detecteur_logo"','android:icon="@drawable/detecteur_logo"\n        android:roundIcon="@drawable/detecteur_logo"',1)
manifest.write_text(m,encoding='utf-8')
print('v3 small finalizer OK')
